import { Drill } from "./types";

// ===== ISINMA DRİLLERİ (10) =====
export const warmupDrills: Drill[] = [
  { id: 1, name: "Hafif Koşu + Kol Çemberleri", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Üst vücut ve omuz eklemini antrenman öncesi aktive etmek, kalp atış hızını kademeli olarak yükseltmek.\n\nUygulama: Salon çevresinde hafif tempoda koşu yapılırken, eş zamanlı olarak kollar öne ve arkaya doğru büyük çemberler çizer. İlk 1 dakika öne, sonraki 1 dakika arkaya çember yapılır. Son dakikada tempo hafifçe artırılır.\n\nSaha ve Oyuncular: Salon çevresi veya 20m alan. Tüm oyuncular aynı anda yapabilir.\n\nÖnemli Noktalar: Kolları düz tutun, çemberleri büyük yapın. Koşu temposunu konuşabilecek düzeyde tutun. Omuzlarda ağrı hissedilirse çember küçültülür.", tags: ["ısınma", "omuz", "kardio"] },
  { id: 2, name: "Diz Yükseltme (High Knees)", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "2 dk", desc: "Drilin Amacı: Kalça fleksörleri ve alt ekstremiteyi aktive etmek, kardiyovasküler sistemi hazırlamak.\n\nUygulama: Yerinde veya ilerleyerek dizler göğüs hizasına çekilir. Her adımda diz kalça seviyesine ulaşmalıdır. Kollar koşu ritmiyle senkronize hareket eder. 20 saniye çalışma, 10 saniye dinlenme şeklinde 4 set yapılır.\n\nÖnemli Noktalar: Sırtı dik tutun, öne eğilmeyin. Ayak topları üzerinde zıplayın. Tempo kademeli artırılmalıdır.", tags: ["ısınma", "bacak", "kardio"] },
  { id: 3, name: "Topuğu Kalçaya Çekme", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "2 dk", desc: "Drilin Amacı: Quadriceps kaslarını ısıtmak ve dinamik esneklik kazandırmak.\n\nUygulama: Hafif koşu sırasında topuklar kalçaya çekilir. Her adımda topuğun kalçaya değmesi hedeflenir. Salonun bir ucundan diğerine ilerleyerek yapılır. Geri dönüşte aynı hareket tekrarlanır.\n\nÖnemli Noktalar: Dizler yere dik kalmalı, öne çıkmamalıdır. Gövde dik tutulmalıdır. Zorlamadan doğal bir ritimde yapılmalıdır.", tags: ["ısınma", "bacak"] },
  { id: 4, name: "Yan Adımlama (Lateral Shuffle)", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Voleybol savunma pozisyonunda kullanılan lateral hareket paternini ısıtmak, iç ve dış bacak kaslarını hazırlamak.\n\nUygulama: Savunma pozisyonunda (dizler bükük, ağırlık ayak toplarında) yanlara kayma adımları yapılır. 5 metre sağa, 5 metre sola şeklinde tekrarlanır. Ayaklar birbirine değmemeli ve çaprazlanmamalıdır.\n\nSaha: 10m genişliğinde alan. Tüm oyuncular paralel şekilde çalışabilir.\n\nÖnemli Noktalar: Kalça düşük kalsın. Adımlar geniş ve kontrollü olsun. Üst vücut sabit kalmalı.", tags: ["ısınma", "çeviklik", "savunma"] },
  { id: 5, name: "Aç-Kapa Zıplama (Jumping Jacks)", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "2 dk", desc: "Drilin Amacı: Tüm vücudu ısıtmak, kalp atış hızını yükseltmek ve koordinasyonu sağlamak.\n\nUygulama: Ayakta düz pozisyonda başlayın. Zıplayarak kolları yana ve yukarı açarken bacakları da yana açın. Tekrar zıplayarak başlangıç pozisyonuna dönün. 30 saniye çalışma, 15 saniye dinlenme şeklinde 3 set yapılır.\n\nÖnemli Noktalar: Yumuşak zemin tercih edin. Ayak bileklerini korumak için ayak toplarına inin. Ritmi koruyun.", tags: ["ısınma", "kardio"] },
  { id: 6, name: "Dinamik Arka Bacak Germe", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Hamstring kaslarını ve kalça eklemini dinamik olarak germek, alt ekstremite esnekliğini artırmak.\n\nUygulama: Yürüyerek her adımda bir bacağı düz şekilde öne savurun, karşı el ayak ucuna uzanır. Ardından diğer bacakla tekrarlayın. Salonun bir ucundan diğerine ilerleyerek yapılır.\n\nÖnemli Noktalar: Bacağı savururken dizden bükmemeye çalışın. Ani ve sert hareketlerden kaçının, kontrollü yapın. Bel bölgesinde ağrı hissederseniz hareket genliğini azaltın.", tags: ["ısınma", "esneklik", "bacak"] },
  { id: 7, name: "Yürüyerek Öne Hamle (Walking Lunge)", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Quadriceps, gluteus ve kalça fleksörlerini aktive etmek, alt vücut kuvvet ısınması sağlamak.\n\nUygulama: Geniş adımlarla öne adım atarak hamle pozisyonuna inin. Ön diz 90 derece bükülmeli, arka diz yere yaklaşmalıdır. Gövde dik kalmalıdır. Her bacak için 10 adım, toplam 2 set yapılır.\n\nÖnemli Noktalar: Diz, ayak ucunu geçmemelidir. Gövdeyi dik tutun, öne eğilmeyin. Denge zorsa önce yarım hamle ile başlayın.", tags: ["ısınma", "bacak", "denge"] },
  { id: 8, name: "Plank 30 Saniye", phase: "Isınma", skill: "Core", level: "Başlangıç", players: "1+", duration: "1 dk", desc: "Drilin Amacı: Core kaslarını aktive ederek omurga stabilizasyonunu sağlamak, antrenman boyunca doğru postür için hazırlamak.\n\nUygulama: Yüzüstü pozisyonda dirsekler ve ayak uçları üzerinde vücudu düz bir çizgide tutun. 30 saniye boyunca pozisyonu koruyun, 15 saniye dinlenin, tekrarlayın.\n\nÖnemli Noktalar: Kalçayı ne çok yukarı ne çok aşağı bırakın. Nefes almayı unutmayın. Sırt düz olmalı, bel çukurlaşmamalıdır.", tags: ["ısınma", "core"] },
  { id: 9, name: "Bantla Omuz Mobilitesi", phase: "Isınma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Omuz eklemini voleybol hareketlerine (servis, smaç, blok) hazırlamak, rotator cuff kaslarını aktive ederek yaralanma riskini azaltmak.\n\nUygulama: Hafif dirençli bant kullanılır. (1) İç rotasyon: Dirsek 90° bükülü, bandı karına doğru çekin (15 tekrar). (2) Dış rotasyon: Dirsek 90° bükülü, bandı dışa doğru açın (15 tekrar). (3) Pull-apart: Kollar öne uzanmış, bandı geriye doğru açın (15 tekrar).\n\nÖnemli Noktalar: Yavaş ve kontrollü yapın. Omuzda ağrı varsa durun. Smaç yapan oyuncular için özellikle önemlidir.", tags: ["ısınma", "omuz", "mobilite"] },
  { id: 10, name: "Core Aktivasyonu (Dead Bug)", phase: "Isınma", skill: "Core", level: "Başlangıç", players: "1+", duration: "2 dk", desc: "Drilin Amacı: Derin core kaslarını (transversus abdominis) aktive ederek antrenman boyunca bel sağlığını korumak.\n\nUygulama: Sırt üstü yatın, kollar tavana doğru uzanmış, dizler 90° bükülü. Karşı kol ve bacağı eş zamanlı olarak yere doğru uzatın, diğer taraf sabit kalır. Yavaşça başlangıca dönün, diğer tarafla tekrarlayın. Her taraf 12 tekrar.\n\nÖnemli Noktalar: Bel yere yapışık kalmalı, ark yapmamalı. Hareket yavaş ve kontrollü olmalı. Nefes verin uzanırken, nefes alın dönerken.", tags: ["ısınma", "core"] },
];

// ===== PAS ODAKLI DRİLLER (8) =====
export const passingDrills: Drill[] = [
  { id: 11, name: "Çift Kol Manşet Duvar Çalışması", phase: "Ana Antrenman", skill: "Manşet", level: "Başlangıç", players: "1", duration: "10 dk", desc: "Drilin Amacı: Temel manşet platform mekaniğini geliştirmek, kol açısı ve top kontrolü üzerinde çalışmak.\n\nUygulama: Duvardan 2-3 metre uzaklıkta durun. Topu duvara doğru manşet ile gönderin ve geri gelen topu tekrar manşet ile karşılayın. Her sette 30 ardışık manşet hedefleyin. 3-5 set yapılır.\n\nÖnemli Noktalar: Kollar düz ve birleşik tutulmalı. Top, bileklerin 5-10 cm üzerindeki düz kısımla karşılanmalıdır. Bacaklar hafif bükülü, ağırlık öne verilmelidir. Kolları yukarı savurmayın, omuzdan hafif itme hareketi yapın.", tags: ["manşet", "bireysel", "temel"] },
  { id: 12, name: "Partner Manşet Alışverişi", phase: "Ana Antrenman", skill: "Manşet", level: "Başlangıç", players: "2", duration: "10 dk", desc: "Drilin Amacı: Karşılıklı manşet ile kontrol, yönlendirme ve tutarlılık geliştirmek.\n\nUygulama: İki oyuncu 4-5 metre mesafede karşı karşıya durur. Biri topu üstten atar, diğeri manşet ile geri gönderir. 20 tekrar sonrası roller değişir. İkinci aşamada her iki oyuncu da manşet kullanır.\n\nÖnemli Noktalar: Topu partnerin göğüs hizasına göndermeyi hedefleyin. Platform açısını kontrol edin. Ayaklarınızı topun altına alın, kollarla yönlendirme yapmayın.", tags: ["manşet", "partner", "temel"] },
  { id: 13, name: "Üçgen Manşet Rotasyonu", phase: "Ana Antrenman", skill: "Manşet", level: "Orta", players: "3", duration: "12 dk", desc: "Drilin Amacı: Hareket halinde manşet kontrolünü geliştirmek, farklı açılardan gelen toplara adaptasyon sağlamak.\n\nUygulama: 3 oyuncu üçgen formasyonda 4-5 metre aralıklarla durur. Top saat yönünde manşetle döndürülür. Her oyuncu manşetle topu sağındaki oyuncuya gönderir, ardından topun gidiş yönüne doğru bir adım kayar. 2 dakika saat yönü, 2 dakika ters yön. Her yön 3 set.\n\nÖnemli Noktalar: Manşetten önce ayaklarınızı topun altına alın. Pas kalitesi düşerse tempo yavaşlatılır. İletişim kurun: 'Bende!' diye çağırın.", tags: ["manşet", "hareket", "takım"] },
  { id: 14, name: "Servis Karşılama Drili", phase: "Ana Antrenman", skill: "Manşet", level: "Orta", players: "3+", duration: "15 dk", desc: "Drilin Amacı: Gerçek servis toplarını manşetle kontrollü şekilde pasör bölgesine yönlendirmek, servis karşılama kalitesini artırmak.\n\nUygulama: Bir oyuncu servis atar, karşı tarafta 2-3 oyuncu karşılama formasyonunda durur. Karşılayan oyuncu manşetle topu 2-3 numara arasındaki hedef bölgeye gönderir. Her oyuncu 10 karşılama yapar, ardından servis atanla yer değiştirilir.\n\nSaha: Tam saha. Hedef bölge file kenarında cone ile belirlenir.\n\nÖnemli Noktalar: Servis öncesi hazır pozisyonda (ayaklarınız omuz genişliğinde, dizler bükük) bekleyin. Topun yönünü erken okuyun. İlk adımınız topun düşeceği noktaya olmalıdır.", tags: ["manşet", "servis karşılama"] },
  { id: 15, name: "Hareket Sonrası Manşet", phase: "Ana Antrenman", skill: "Manşet", level: "Orta", players: "2", duration: "10 dk", desc: "Drilin Amacı: Dinamik koşullar altında manşet kalitesini artırmak, hareket sonrası dengelenerek pas verme becerisini geliştirmek.\n\nUygulama: Oyuncu sağa 3 metre kayar, partner topu o yöne atar, oyuncu manşetle karşılar. Ardından sola 3 metre kayar ve tekrarlar. Her yön 10 tekrar, toplam 3 set.\n\nÖnemli Noktalar: Son adımda durun ve dengelenin, hareket halinde manşet yapmayın. Platform açısını hedefe göre ayarlayın. Bacaklardan güç alın.", tags: ["manşet", "hareket"] },
  { id: 16, name: "Derinlik Manşet Drili", phase: "Ana Antrenman", skill: "Manşet", level: "İleri", players: "2", duration: "10 dk", desc: "Drilin Amacı: Farklı mesafelerden gelen toplara manşet ile güç ve açı ayarı yapabilmeyi geliştirmek.\n\nUygulama: Partner bir kısa (2m), bir uzun (6m) top atar. Oyuncu her ikisini de manşetle aynı hedef noktaya (pasör bölgesi) gönderir. 15 tekrar × 3 set.\n\nÖnemli Noktalar: Kısa toplarda platform açısını dikleştirin. Uzun toplarda bacakları daha çok kullanarak güç verin. Her iki top için de hedef aynı nokta olmalıdır.", tags: ["manşet", "kontrol"] },
  { id: 17, name: "Stresli Manşet (Multi-ball)", phase: "Ana Antrenman", skill: "Manşet", level: "İleri", players: "2+", duration: "10 dk", desc: "Drilin Amacı: Peş peşe gelen toplara hızlı tepki verme, baskı altında manşet kalitesini koruma ve dayanıklılık geliştirme.\n\nUygulama: Koç veya partner, 2-3 saniye aralıklarla farklı yönlere top atar. Oyuncu her topu manşetle hedef bölgeye gönderir. 30 saniye çalışma, 30 saniye dinlenme. 5 set.\n\nÖnemli Noktalar: Manşet sonrası hemen hazır pozisyona dönün. Kalite düşmeye başlarsa tempo azaltılır. Son setlerde yorgunlukla gelen hataları minimize etmeye çalışın.", tags: ["manşet", "baskı", "refleks"] },
  { id: 18, name: "Manşet ile Hedef İsabetliliği", phase: "Ana Antrenman", skill: "Manşet", level: "Orta", players: "2", duration: "10 dk", desc: "Drilin Amacı: Manşetle belirli hedeflere tutarlı pas gönderme doğruluğunu artırmak.\n\nUygulama: Sahada 3 farklı hedef bölge (cone veya işaret) belirlenir: sol, orta, sağ. Partner farklı açılardan top atar, oyuncu çağrılan hedef bölgeye manşetle gönderir. 15 tekrar × 3 set. Başarı oranı kaydedilir.\n\nÖnemli Noktalar: Platform açısını hedefe göre değiştirin. Gövdenizi hedefe dönün. Tutarlılık, güçten daha önemlidir.", tags: ["manşet", "hedef", "doğruluk"] },
];

// ===== SET/PASÖR DRİLLERİ (6) =====
export const settingDrills: Drill[] = [
  { id: 19, name: "Üçgen Pas Drili", phase: "Ana Antrenman", skill: "Pas", level: "Orta", players: "3", duration: "10 dk", desc: "Drilin Amacı: Parmak uçlarıyla hassas top kontrolünü geliştirmek, farklı açılara üstten pas gönderme becerisini artırmak.\n\nUygulama: 3 oyuncu üçgen formasyonda 4 metre aralıklarla durur. Top üstten pas ile sırayla döndürülür. 2 dakika saat yönü, 2 dakika ters yön. Her set 20 pas. 3 set.\n\nÖnemli Noktalar: Elleri üçgen şeklinde hazırlayın. Topu alın hizasında karşılayın. Bileklerden güç verin, kolları germekten kaçının.", tags: ["pas", "üstten pas", "partner"] },
  { id: 20, name: "Pasör Ayak Çalışması", phase: "Ana Antrenman", skill: "Pasörlük", level: "İleri", players: "2", duration: "15 dk", desc: "Drilin Amacı: Pasörün hızlı pozisyon alma ve farklı konumlardan kaliteli set yapma becerisini geliştirmek.\n\nUygulama: Pasör file ortasında başlar. Koç topu sahanın farklı noktalarına atar. Pasör cross-step veya shuffle ile topu karşılar ve 4 numaraya set yapar. Ardından hızla merkeze döner ve yeni top beklenir. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Son adımda dengelenerek set yapın. Ayaklar omuz genişliğinde ve hedefe dönük olmalı. Penetrasyon hızı her zaman yüksek tutulmalıdır.", tags: ["pasör", "ayak", "hız"] },
  { id: 21, name: "Sırt Set Drili", phase: "Ana Antrenman", skill: "Pasörlük", level: "İleri", players: "3", duration: "12 dk", desc: "Drilin Amacı: Pasörün arkasındaki atakçıya (genellikle pasör çaprazı veya 2 numaradaki smaçör) hassas set yapabilme tekniğini geliştirmek.\n\nUygulama: Pasör file kenarında pozisyon alır. Koç farklı noktalardan top gönderir. Pasör topu karşılayarak arkasına (2 numaraya) set yapar. Atakçı seti karşılayarak kalitesini değerlendirir. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Topu alın hizasında karşılayın. Sırt set ile önden seti aynı başlangıç pozisyonunda yapın (aldatma). Omuzları hafifçe arkaya açarak bilek gücüyle topu itin.", tags: ["pasör", "sırt set"] },
  { id: 22, name: "Jump Set Drili", phase: "Ana Antrenman", skill: "Pasörlük", level: "İleri", players: "2", duration: "12 dk", desc: "Drilin Amacı: Havada set yapma tekniğini geliştirmek, hava dengesi ve zamanlama üzerinde çalışmak.\n\nUygulama: Partner yüksek top atar. Pasör zıplayarak havada set yapar. Set hem öne hem arkaya yapılarak çeşitlilik sağlanır. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Zıplama zamanlamasını topun geliş hızına göre ayarlayın. Havada gövdenizi sabit tutun. İniş dengenize dikkat edin. Jump set, rakip blokçuyu şaşırtmak için kullanılır.", tags: ["pasör", "jump set"] },
  { id: 23, name: "Geçiş Seti (Transition Set)", phase: "Ana Antrenman", skill: "Pasörlük", level: "Orta", players: "4+", duration: "15 dk", desc: "Drilin Amacı: Savunma sonrası hızlı pozisyon alarak kaliteli set yapma becerisini geliştirmek.\n\nUygulama: 6 kişi sahada pozisyon alır. Koç topu bir tarafa atar (savunma simülasyonu), oyuncular savunma yapar, pasör hızla file kenarına koşar ve gelen topu set yapar. Atakçılar sete göre atak simülasyonu yapar. Rally başına 5 dokunuş, toplam 15 rally.\n\nÖnemli Noktalar: Pasör savunma sonrası hızla ağ kenarına koşmalı. İlk pas kalitesine göre set seçimi yapılmalı. Geçiş setleri genellikle daha yüksek ve güvenli olmalıdır.", tags: ["pasör", "geçiş", "hız"] },
  { id: 24, name: "Quick Set Zamanlama", phase: "Ana Antrenman", skill: "Pasörlük", level: "İleri", players: "3", duration: "12 dk", desc: "Drilin Amacı: Pasör ve orta oyuncu arasındaki 1. tempo (quick) set zamanlamasını mükemmelleştirmek.\n\nUygulama: Pasör file kenarında, orta oyuncu pasörün yanında hazırlanır. Koç topu pasöre gönderir, orta oyuncu koşmaya başlar, pasör topu tam doğru zamanda ve yükseklikte bırakır. Orta oyuncu havada karşılar. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Orta oyuncu erken kalkmalı. Pasörle göz teması çok önemlidir. Set, orta oyuncunun elinin ulaşabileceği yükseklikte ve hızda olmalıdır.", tags: ["pasör", "quick", "tempo"] },
];

// ===== ATAK DRİLLERİ (7) =====
export const attackDrills: Drill[] = [
  { id: 25, name: "Çapraz Atak Drili", phase: "Ana Antrenman", skill: "Atak", level: "Orta", players: "3+", duration: "15 dk", desc: "Drilin Amacı: 4 numaradan çapraz atak vuruş tekniğini, kol mekaniğini ve doğru zamanlama ile açı kontrolünü geliştirmek.\n\nUygulama: Pasör file kenarında set yapar. Smaçör 4 numaradan 3-4 adımlık yaklaşma ile gelir ve çapraz yöne (sahanın karşı köşesine) atak yapar. Her smaçör 10 atak × 3 set yapar.\n\nSaha: Tam saha, file yüksekliği seviyeye uygun.\n\nÖnemli Noktalar: Son iki adımı hızlandırın (brake step). Kolu tam uzanımda, topu en yüksek noktada vurun. Bilek açısını çapraza doğru yönlendirin. İnişte her iki ayak üzerine dengeli inin.", tags: ["atak", "çapraz", "smaç"] },
  { id: 26, name: "Çizgi Atağı", phase: "Ana Antrenman", skill: "Atak", level: "Orta", players: "3+", duration: "12 dk", desc: "Drilin Amacı: Çizgi boyunca dar açılı atak vuruşu yapmayı öğrenmek, bilek kontrolü ve hedefleme becerisi geliştirmek.\n\nUygulama: Smaçör 4 numaradan yaklaşır ve topu yan çizgi boyunca (çizgi atağı) vurur. Hedef: topun sahanın arka köşesine, yan çizgi kenarına düşmesi. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Bilek açısını çizgiye doğru kırın. Vücut çapraza dönük gibi görünsün ama bilek son anda çizgiye yönlensin (aldatma). Bloğun tek eli varsa çizgiyi açık bırakabilir, bu avantajı kullanın.", tags: ["atak", "çizgi", "hedef"] },
  { id: 27, name: "Yaklaşma + Smaç Tekniği", phase: "Ana Antrenman", skill: "Atak", level: "Başlangıç", players: "2+", duration: "15 dk", desc: "Drilin Amacı: Smaç için doğru 3-4 adımlık yaklaşma mekaniğini, zıplama tekniğini ve vuruş temelini öğretmek.\n\nUygulama: Smaçör file kenarından 3-4 metre geride başlar. (1) Sol adım (yavaş), (2) Sağ adım (hızlanma), (3) Sol ayak kapatma (hızlı) ve çift ayakla zıplama. Havada kol çekişi ve top vuruşu. İlk aşamada topsuz, sonra atılan topla, en son setle yapılır.\n\nÖnemli Noktalar: Son iki adım hızlı ve geniş olmalı. Kolları arkaya sallayarak zıplama gücü artırılır. Topu en yüksek noktada vurun. İniş dengesine dikkat edin.", tags: ["atak", "yaklaşma", "temel"] },
  { id: 28, name: "Tool Shot (Blok Kullanma)", phase: "Ana Antrenman", skill: "Atak", level: "İleri", players: "4+", duration: "12 dk", desc: "Drilin Amacı: Bloğun dış elini kullanarak topu saha dışına yönlendirme tekniğini (tool/wipe) öğrenmek.\n\nUygulama: Blokçu filede blok pozisyonunda durur. Smaçör yaklaşarak topu bloğun dış eline doğru vurur, bilek açısıyla topu dışarı yönlendirir. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Bloğun ellerini izleyin ve dış eli hedefleyin. Bilek açısını dışa doğru çevirin. Anten yakınında daha etkilidir. Bloğu okumadan denemeyin.", tags: ["atak", "tool", "ileri"] },
  { id: 29, name: "Tip/Roll Shot", phase: "Ana Antrenman", skill: "Atak", level: "Orta", players: "3+", duration: "10 dk", desc: "Drilin Amacı: Yumuşak parmak ucu veya avuç içi vuruşuyla bloğun arkasına kısa top düşürme tekniğini geliştirmek.\n\nUygulama: Smaçör normal yaklaşma yapar (sert smaç gibi görünmeli). Son anda bilek hareketini yumuşatarak topu bloğun arkasına, savunmanın boş bölgesine düşürür. Tip shot (parmak ucu) ve roll shot (avuç ile yuvarlama) ayrı ayrı çalışılır. 10 tekrar × 2 set.\n\nÖnemli Noktalar: Son ana kadar sert smaç gibi görünün (aldatma). Sadece bilek hareketini değiştirin. Savunmanın boş bölgesini hedefleyin.", tags: ["atak", "yumuşak", "taktik"] },
  { id: 30, name: "Arka Sıra Atak Drili", phase: "Ana Antrenman", skill: "Atak", level: "İleri", players: "3+", duration: "15 dk", desc: "Drilin Amacı: 3 metre gerisinden etkili atak yapabilmeyi (pipe, D-ball) öğrenmek, arka sıra atak zamanlamasını geliştirmek.\n\nUygulama: Smaçör 3 metre çizgisinin gerisinden yaklaşır. Pasör yüksek ve uzun set verir. Smaçör 3 metre çizgisini basmadan zıplar ve atak yapar. Pipe (orta), D-ball (çapraz arka sıra) pozisyonları ayrı ayrı çalışılır. 10 tekrar × 3 set.\n\nÖnemli Noktalar: 3 metre çizgisini kesinlikle geçmeyin. Yaklaşma açınızı geniş tutun. İniş dengenize dikkat edin. Set yeterince yüksek ve uzun olmalıdır.", tags: ["atak", "arka sıra", "pipe"] },
  { id: 31, name: "Atak Kol Mekaniği (Duvar)", phase: "Ana Antrenman", skill: "Atak", level: "Başlangıç", players: "1", duration: "10 dk", desc: "Drilin Amacı: Doğru kol çekişi, dirsek pozisyonu ve vuruş mekaniğini zıplamadan, kontrollü ortamda pekiştirmek.\n\nUygulama: Duvardan 2 metre uzaklıkta durun. Topu elinize alın, kolu kulak hizasına getirin (dirsek yüksek, el arkada). Topu duvara sert vurun ve geri dönen topu yakalayın. 15 tekrar × 4 set.\n\nÖnemli Noktalar: Dirseği her zaman yüksek tutun. Topu vuruş anında bileğinizi snap yapın. Kol tam uzanımda topu vurun. Kol hareketi sırasında gövde rotasyonu da yapılmalıdır.", tags: ["atak", "temel", "mekanik"] },
];

// ===== SAVUNMA DRİLLERİ (7) =====
export const defenseDrills: Drill[] = [
  { id: 32, name: "Libero Refleks Drili", phase: "Ana Antrenman", skill: "Savunma", level: "İleri", players: "2", duration: "10 dk", desc: "Drilin Amacı: Hızlı tepki, refleks ve pancake kurtarış becerisini geliştirmek, baskı altında savunma kalitesini artırmak.\n\nUygulama: Koç veya partner 2-3 metre mesafeden hızlı top atar (farklı yön ve yüksekliklerde). Libero her topu kurtarmaya çalışır: manşet, pancake, dalış. 20 top × 3 set, setler arası 1 dakika dinlenme.\n\nÖnemli Noktalar: Her zaman düşük pozisyonda hazır olun. Gözleriniz topun çıkış noktasında olsun. Kurtarış sonrası hemen ayağa kalkın ve hazır pozisyona dönün.", tags: ["savunma", "libero", "refleks"] },
  { id: 33, name: "Dalış Kurtarış (Dive)", phase: "Ana Antrenman", skill: "Savunma", level: "Orta", players: "2", duration: "10 dk", desc: "Drilin Amacı: Yana ve öne dalış ile ulaşılamayacak topları güvenli şekilde kurtarma tekniğini öğrenmek.\n\nUygulama: (1) Kuru antrenman: Dalış mekaniği, düşme ve yuvarlanma topsuz çalışılır. (2) Partner 3-4 metre uzağa kısa top atar, oyuncu dalarak kurtarır. (3) Rastgele yönlere top atılır. Her aşama 10 tekrar × 2 set.\n\nÖnemli Noktalar: Dalışı alçak pozisyondan başlatın. Çeneyi göğse yapıştırın (baş koruması). Gövdenizle zemine yumuşak şekilde kayın. Dalış sonrası hemen ayağa kalkma pratiği yapın.", tags: ["savunma", "dalış"] },
  { id: 34, name: "Platform Savunma Drili", phase: "Ana Antrenman", skill: "Savunma", level: "Başlangıç", players: "2", duration: "10 dk", desc: "Drilin Amacı: Düşük pozisyonda platform oluşturarak temel savunma tekniğini geliştirmek.\n\nUygulama: Oyuncu savunma pozisyonunda (dizler bükük, ağırlık öne) bekler. Partner farklı açılardan orta şiddette top atar. Oyuncu platform ile topu kontrol eder. 15 tekrar × 3 set.\n\nÖnemli Noktalar: Düşük pozisyonda kalın, çok dik durmayın. Kollar düz ve sert tutulmalı. Topun altına girin, kollarla savurmayın. Ağırlığınız ayak toplarınızda olsun.", tags: ["savunma", "temel"] },
  { id: 35, name: "Blok Arkası Savunma", phase: "Ana Antrenman", skill: "Savunma", level: "Orta", players: "6", duration: "15 dk", desc: "Drilin Amacı: Blok arkasında doğru pozisyon alarak, bloktan sızan topları kurtarma organizasyonunu geliştirmek.\n\nUygulama: 3 blokçu filede, 3 savunmacı arkada pozisyon alır. Koç karşı taraftan atak simülasyonu yapar. Blokçular blok yapar, savunmacılar bloğun kapatmadığı açıya göre pozisyon alır. 10 rally × 3 set.\n\nSaha: Tam saha, 6 kişi.\n\nÖnemli Noktalar: Blokçunun arkasına geçmeyin, gölgede kalmayın. Blokçunun kapattığı açıyı bilin ve diğer açıyı kapatın. İletişim hayati önem taşır.", tags: ["savunma", "blok arkası", "takım"] },
  { id: 36, name: "Cross-court Savunma", phase: "Ana Antrenman", skill: "Savunma", level: "Orta", players: "4+", duration: "12 dk", desc: "Drilin Amacı: Çapraz atak toplarını doğru pozisyonda kurtarma becerisini geliştirmek.\n\nUygulama: Bir smaçör 4 numaradan çapraz atak yapar. Karşı sahada savunmacılar pozisyon alır. Savunmacı çapraz atak açısını okuyarak topun düşeceği noktaya gider ve manşetle kurtarır. 10 atak × 3 set.\n\nÖnemli Noktalar: Atakçının omzunu ve kol açısını izleyin. Topun yönünü erken tahmin edin. Savunma pozisyonunu blokçunun kapattığı alana göre ayarlayın.", tags: ["savunma", "çapraz"] },
  { id: 37, name: "Multi-ball Savunma", phase: "Ana Antrenman", skill: "Savunma", level: "İleri", players: "2+", duration: "10 dk", desc: "Drilin Amacı: Peş peşe gelen toplara ardışık savunma yaparak dayanıklılık ve refleks geliştirmek.\n\nUygulama: Koç 2-3 saniye aralıklarla farklı yön ve şiddetlerde top fırlatır. Savunmacı her topu kurtarmaya çalışır. 30 saniye çalışma, 30 saniye dinlenme. 5 set.\n\nÖnemli Noktalar: Her kurtarış sonrası hemen hazır pozisyona dönün. Pozisyon kalitesinden ödün vermeyin. Yorulunca formu bozmak yerine tempoyu azaltın.", tags: ["savunma", "multi-ball", "dayanıklılık"] },
  { id: 38, name: "Pancake Kurtarış Drili", phase: "Ana Antrenman", skill: "Savunma", level: "İleri", players: "2", duration: "8 dk", desc: "Drilin Amacı: El sırtıyla yerden top kurtarma (pancake) tekniğini öğrenmek ve mükemmelleştirmek.\n\nUygulama: (1) Kuru çalışma: Eli düz şekilde yere koyup kaldırma pratiği. (2) Partner yakın mesafeden topu yere doğru atar, oyuncu eli topun altına kaydırarak pancake yapar. (3) Daha uzak mesafeden dalış + pancake kombinasyonu. Her aşama 8 tekrar × 2 set.\n\nÖnemli Noktalar: El düz ve yere paralel olmalı. Elin sırtı zemine, parmaklar ileriye bakmalı. Topun tam altına ulaşın. Dalış + pancake kombinasyonunda çeneyi koruyun.", tags: ["savunma", "pancake", "ileri"] },
];

// ===== BLOK DRİLLERİ (5) =====
export const blockDrills: Drill[] = [
  { id: 39, name: "Blok-Savunma Geçişi", phase: "Ana Antrenman", skill: "Blok", level: "İleri", players: "6+", duration: "15 dk", desc: "Drilin Amacı: Blok sonrası hızla savunma pozisyonuna geçiş yapabilmeyi geliştirmek, sürekli hareket halinde oyun yeteneği kazandırmak.\n\nUygulama: Blokçu filede blok yapar → iniş → hızla 3 metre gerisine çekilir → savunma pozisyonu alır → koçun attığı topu savunur → tekrar blok pozisyonuna döner. 8 tekrar × 3 set.\n\nÖnemli Noktalar: Blok sonrası hemen geri çekilin, durmayın. Savunma pozisyonuna geçerken gözler top üzerinde olsun. Kondisyon gerektiren bir dril, tempolu yapılmalı.", tags: ["blok", "geçiş", "savunma"] },
  { id: 40, name: "Shadow Block", phase: "Ana Antrenman", skill: "Blok", level: "Başlangıç", players: "1+", duration: "10 dk", desc: "Drilin Amacı: Blok pozisyonu, el yerleşimi ve zıplama mekaniklerini topsuz ortamda pekiştirmek.\n\nUygulama: Oyuncu file karşısında durur. Koçun işaretiyle sağa veya sola kayar ve blok zıplaması yapar. Eller fileyi aşacak şekilde uzatılır, parmaklar açık ve sert tutulur. Her yön 10 tekrar × 3 set.\n\nÖnemli Noktalar: Ayaklar paralel tutulmalı. Zıplarken kolları yukarı itin, yana açmayın. Eller fileye değmemeli (net fault). İnişte dizleri hafif bükün.", tags: ["blok", "temel"] },
  { id: 41, name: "Çift Blok Koordinasyonu", phase: "Ana Antrenman", skill: "Blok", level: "Orta", players: "4+", duration: "15 dk", desc: "Drilin Amacı: İki blokçunun eş zamanlı ve boşluksuz blok yapma becerisini geliştirmek.\n\nUygulama: İki blokçu file kenarında yan yana durur. Koç karşı taraftan atak yönünü belirler, blokçular birlikte kaymalar yaparak o noktada çift blok yapar. 10 tekrar × 3 set.\n\nÖnemli Noktalar: İki blokçu arasında boşluk kalmamalı (omuz omuza). Dıştaki blokçu çizgiyi kapatsın, içteki çaprazı kapatsın. Eş zamanlı zıplayın. Blok öncesi sesli iletişim kurun.", tags: ["blok", "takım", "koordinasyon"] },
  { id: 42, name: "Read Block vs Commit", phase: "Ana Antrenman", skill: "Blok", level: "İleri", players: "4+", duration: "12 dk", desc: "Drilin Amacı: Pasörü okuyarak blok pozisyonu alma (read block) ile direkt atakçıya atlama (commit block) arasındaki karar verme becerisini geliştirmek.\n\nUygulama: Karşı sahada pasör ve 2-3 atakçı bulunur. Blokçu pasörü izler: (1) Quick set gelirse commit block (erken zıplama), (2) Dış set gelirse read block (okuyarak kayma ve zıplama). 15 rally × 3 set.\n\nÖnemli Noktalar: Pasörün omuzlarını ve el pozisyonunu izleyin. Commit block sadece kesin quick durumlarda. Read block'ta lateral hareket hızı kritik. Kararsız kalmak en kötü seçenektir, bir karar verin ve uygulayın.", tags: ["blok", "okuma", "karar"] },
  { id: 43, name: "Lateral Block Kayma", phase: "Ana Antrenman", skill: "Blok", level: "Orta", players: "2+", duration: "10 dk", desc: "Drilin Amacı: File boyunca hızlı yatay hareket ederek blok pozisyonu alma becerisini geliştirmek.\n\nUygulama: Blokçu filenin bir ucunda başlar. Koçun işaretiyle sağa veya sola kayar ve blok zıplaması yapar. Cross-step (çapraz adım) ve shuffle (kayma) teknikleri ayrı ayrı çalışılır. Her teknik 10 tekrar × 2 set.\n\nÖnemli Noktalar: Cross-step uzun mesafeler için, shuffle kısa mesafeler için kullanılır. Son adımda ayakları paralele getirin. Kayma sırasında elleri yüksekte tutun, aşağı indirmeyin.", tags: ["blok", "lateral", "ayak"] },
];

// ===== SERVİS DRİLLERİ (5) =====
export const serveDrills: Drill[] = [
  { id: 44, name: "Servis Hedef Çalışması", phase: "Ana Antrenman", skill: "Servis", level: "Orta", players: "1+", duration: "10 dk", desc: "Drilin Amacı: Servis isabetliliğini artırmak, sahada belirlenen hedef bölgelere tutarlı şekilde servis atabilmeyi geliştirmek.\n\nUygulama: Karşı sahada 6 bölge (1-6) cone ile işaretlenir. Koç bölge numarası söyler, oyuncu o bölgeye servis atar. 10 servis × 3 set. Her sette başarı oranı kaydedilir. Hedef: %70+ isabet.\n\nÖnemli Noktalar: Servis öncesi hedefi gözünüzle belirleyin. Top atma yüksekliğini sabit tutun. Kol takibini hedefe doğru yönlendirin. Rüzgar varsa (dış saha) bunu hesaba katın.", tags: ["servis", "hedef", "doğruluk"] },
  { id: 45, name: "Jump Float Servis", phase: "Ana Antrenman", skill: "Servis", level: "Orta", players: "1+", duration: "12 dk", desc: "Drilin Amacı: Zıplayarak atılan dönüşsüz (float) servis tekniğini öğrenmek. Topun havadaki düzensiz hareketi karşılamayı zorlaştırır.\n\nUygulama: Çizginin 1-2 metre gerisinden başlayın. (1) Topu vücut hattının önüne düşük atın. (2) 2-3 adım koşu ile tek veya çift ayakla zıplayın. (3) Kolu düz tutarak topu tam ortasından vurun. (4) Kol takibini durdurun (follow-through yapmayın). 15 servis × 3 set.\n\nÖnemli Noktalar: Topu çok yükseğe atmayın (el yüksekliğinde yeterli). Topspin vermeyin, topun tam merkezine vurun. Kolunuzu son anda durdurun (bu float etkisi yaratır). Aynı ritmi her serviste koruyun.", tags: ["servis", "float", "jump"] },
  { id: 46, name: "Jump Topspin Servis", phase: "Ana Antrenman", skill: "Servis", level: "İleri", players: "1+", duration: "15 dk", desc: "Drilin Amacı: Zıplayarak güçlü topspin servis atma tekniğini geliştirmek. En hızlı ve güçlü servis türüdür.\n\nUygulama: Çizginin 3-4 metre gerisinden başlayın. (1) Topu yüksek ve önünüze atın (3-4 metre yüksek). (2) 3-4 adımlık hızlı koşu ile güçlü sıçrama. (3) Kol tam uzanımda, bilek snap ile topspin vererek vuruş. (4) Gövde rotasyonu ile güç artırma. 10 servis × 3 set.\n\nÖnemli Noktalar: Top atışı her şeyin temeli - tutarlı olmalı. Bilek snap'i ile güçlü topspin oluşturun. Koşu ritminizi sabit tutun. İniş dengeli olmalı, ayak bileklerine dikkat edin.", tags: ["servis", "topspin", "güç"] },
  { id: 47, name: "Alttan Servis Temeli", phase: "Ana Antrenman", skill: "Servis", level: "Başlangıç", players: "1+", duration: "8 dk", desc: "Drilin Amacı: Yeni başlayanlar için temel alttan servis mekaniğini öğretmek, topu güvenle karşı sahaya geçirmeyi sağlamak.\n\nUygulama: Servis çizgisinde durun. (1) Topu vuracak olmayan elinizle bel hizasında tutun. (2) Vuruş eli yumruk veya düz avuç yapın. (3) Topu bırakın (yukarı atmayın) ve aynı anda kolunuzu arkadan öne sallayarak vurun. (4) Kol takibini hedefe doğru yapın. 15 servis × 3 set.\n\nÖnemli Noktalar: Topu havaya atmayın, sadece bırakın ve vurun. Kolunuzu düz tutun, dirsekten bükmeyin. Adım atarak güç ekleyin. Hedefi belirleyerek atın.", tags: ["servis", "temel", "alttan"] },
  { id: 48, name: "Servis Baskısı Drili", phase: "Ana Antrenman", skill: "Servis", level: "İleri", players: "2+", duration: "10 dk", desc: "Drilin Amacı: Maç baskısı altında servis kalitesini korumayı öğrenmek, mental dayanıklılık geliştirmek.\n\nUygulama: Oyuncu 5 ardışık servis atar, hedef: 5'te 4'ünü belirlenen bölgeye isabet ettirmek. Başaramazsa en başa döner. 3 başarılı tur tamamlanana kadar devam edilir. Takım versiyonu: tüm oyuncular sırayla atar, ilk başarısız olan koşu cezası alır.\n\nÖnemli Noktalar: Baskı altında nefes kontrolü uygulayın. Kendi servis ritminize sadık kalın. Maç simülasyonu: 24-24 skoru hayal edin. Risk/ödül dengesini koruyun.", tags: ["servis", "baskı", "mental"] },
];

// ===== OYUN/TAKTİK DRİLLERİ (22) =====
export const gameDrills: Drill[] = [
  { id: 49, name: "6'ya 6 Kontrollü Oyun", phase: "Oyun", skill: "Taktik", level: "Orta", players: "12", duration: "20 dk", desc: "Drilin Amacı: Tam saha maç simülasyonuyla rotasyonları, formasyon geçişlerini ve takım oyununu pekiştirmek.\n\nUygulama: İki takım 6'şar kişi ile normal kurallarla oynar. Özel kural: Her rally minimum 3 dokunuş zorunludur. 25 sayılık set oynanır. Rotasyonlar normal maç kurallarına göre yapılır.\n\nÖnemli Noktalar: Her rotasyonda pozisyonları bilin. İletişim her dokunuşta olmalı. Hata sonrası moral düşüklüğüne izin vermeyin, bir sonraki sayıya odaklanın.", tags: ["oyun", "maç", "takım"] },
  { id: 50, name: "4'e 4 Mini Maç", phase: "Oyun", skill: "Taktik", level: "Başlangıç", players: "8", duration: "15 dk", desc: "Drilin Amacı: Daha az kişiyle daha fazla top dokunuşu sağlayarak temel oyun becerilerini geliştirmek.\n\nUygulama: Yarım sahada (3m x 9m veya badminton sahası boyutlarında) 4'er kişilik takımlarla oynanır. Normal kurallar geçerlidir. Küçük saha daha fazla dokunuş ve iletişim gerektirir. 15 sayılık setler oynanır.\n\nÖnemli Noktalar: Küçük sahada pozisyon disiplini daha da önemlidir. Her oyuncu hem savunma hem atak yapmalıdır. İletişim çok sık olmalıdır.", tags: ["oyun", "mini maç"] },
  { id: 51, name: "King of the Court", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6+", duration: "15 dk", desc: "Drilin Amacı: Rekabet ortamında side-out becerisi ve baskı altında performans geliştirmek.\n\nUygulama: 3'er kişilik takımlar oluşturulur. Bir takım 'kral' tarafında (servis alır), diğerleri sırada bekler. Kral tarafı sayı alırsa kalır ve puan kazanır. Kaybederse sıraya geçer, yeni takım gelir. Sıradaki takım her zaman servis atar.\n\nOyun Kuralları: Kral tarafı yalnızca side-out yaparak sayı alabilir. İlk 10 puana ulaşan takım kazanır. Kaybeden takım sıraya geçerken 5 şınav yapar.\n\nÖnemli Noktalar: İlk pas kalitesi hayati önem taşır. Basit ve kontrollü oynayın. Takım içi iletişim sürekli olmalıdır.", tags: ["oyun", "eğlence", "rekabet"] },
  { id: 52, name: "Wash Drill", phase: "Oyun", skill: "Taktik", level: "İleri", players: "12", duration: "20 dk", desc: "Drilin Amacı: Side-out ve transition performansını aynı rally içinde değerlendirmek, sayı alma disiplini kazandırmak.\n\nUygulama: Rally 1: A takımı servis karşılar (side-out). Rally 2: Hemen ardından koç B takımına freeball atar (transition). Bir takımın puan alması için her iki rally'yi de kazanması gerekir. İlk 5 puana ulaşan kazanır.\n\nÖnemli Noktalar: İki ardışık rally kazanmak zor olduğu için mental güç gerekir. Konsantrasyonu her iki rallyde de yüksek tutun. Bu dril maç sonu baskısını simüle eder.", tags: ["oyun", "wash", "side-out"] },
  { id: 53, name: "Side-out Drili", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6+", duration: "15 dk", desc: "Drilin Amacı: Karşı servis alıp ilk atakta sayı alma (side-out) oranını artırmak.\n\nUygulama: A takımı her zaman servis karşılar. 10 rally oynanır. A takımının ilk atakta sayı alma oranı hesaplanır. Hedef: %60+ side-out oranı. Ardından takımlar değişir.\n\nÖnemli Noktalar: İlk pas kalitesi her şeyi belirler. İlk temasta hata oranını minimize edin. Pasör kolay set versin, atakçı güvenli oynasın.", tags: ["oyun", "side-out"] },
  { id: 54, name: "Transition Oyunu", phase: "Oyun", skill: "Taktik", level: "İleri", players: "12", duration: "20 dk", desc: "Drilin Amacı: Savunma → set → atak geçiş hızını ve organizasyonunu geliştirmek.\n\nUygulama: Koç bir tarafa atak simülasyonu yapar. O taraf savunur → pasör set yapar → atakçı atak yapar. Karşı taraf da aynı şekilde devam eder. Rally durana kadar sürer. 15 rally × 3 set.\n\nÖnemli Noktalar: Savunma sonrası herkes pozisyonuna koşmalı. Pasör her zaman önce ağ kenarına ulaşmalı. Geçiş setleri yüksek ve güvenli olmalı.", tags: ["oyun", "geçiş", "sürekli"] },
  { id: 55, name: "Freeball Rally", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6+", duration: "12 dk", desc: "Drilin Amacı: Kolay topla (freeball) başlayan rallilerde formasyon ve build-up çalışması yapmak.\n\nUygulama: Koç bir tarafa kolay top atar (freeball). O taraf 3 dokunuşla organize atak yapar. Rally doğal şekilde devam eder. 15 rally × 2 set.\n\nÖnemli Noktalar: Freeball geldiğinde herkes pozisyona koşsun. Pasör hazır olsun. İlk temasta kaliteli pas verin, kolay topları harcamayın.", tags: ["oyun", "freeball"] },
  { id: 56, name: "2'ye 2 Plaj Stili", phase: "Oyun", skill: "Taktik", level: "Başlangıç", players: "4", duration: "15 dk", desc: "Drilin Amacı: Daha az kişiyle top dokunuş sayısını artırmak, iletişim ve çok yönlü oyunculuk geliştirmek.\n\nUygulama: Plaj voleybol kurallarıyla 2'şer kişilik takımlar oynar. Saha boyutu 8m x 8m. 15 sayılık set. Her oyuncu hem savunma hem atak yapmalıdır.\n\nÖnemli Noktalar: İletişim sürekli olmalı ('bende!', 'senin!'). Her oyuncu her pozisyonu oynayabilmeli. Rüzgarı hesaba katın (dış sahada).", tags: ["oyun", "plaj", "eğlence"] },
  { id: 57, name: "3'e 3 Karşılama Odaklı", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6", duration: "15 dk", desc: "Drilin Amacı: 3 kişilik takımlarla servis karşılama ve organize atak becerisini geliştirmek.\n\nUygulama: 3'er kişilik takımlar yarım sahada oynar. Özel kural: Servis karşılama manşetle yapılmak zorunda. 3 dokunuş zorunlu. 15 sayılık set.\n\nÖnemli Noktalar: Sorumluluk alanlarını net belirleyin. Araya düşen toplarda 'bende!' diye çağırın. Her rally sonrası pozisyona dönün.", tags: ["oyun", "karşılama"] },
  { id: 58, name: "Pepper (Isınma Oyunu)", phase: "Oyun", skill: "Genel", level: "Başlangıç", players: "2", duration: "5 dk", desc: "Drilin Amacı: Dig → set → spike döngüsüyle temel becerileri ısınma formatında çalışmak, kontrol ve refleks geliştirmek.\n\nUygulama: İki oyuncu 3-4 metre mesafede karşı karşıya durur. A oyuncusu topu B'ye hafif atar (spike), B savunur (dig), A set yapar, B spike yapar, A savunur... Döngü kesintisiz devam eder. 3 dakika aralıksız.\n\nÖnemli Noktalar: Kontrol her şeyden önemli, sert vurmayın. Topu partnerin manşet yapabileceği noktaya gönderin. Bu bir rekabet değil, işbirliği drilidir.", tags: ["oyun", "pepper", "ısınma"] },
  { id: 59, name: "Atak Kaveraj Drili", phase: "Oyun", skill: "Taktik", level: "İleri", players: "6+", duration: "12 dk", desc: "Drilin Amacı: Smaç sonrası bloktan dönen topları kurtarma organizasyonunu (coverage) geliştirmek.\n\nUygulama: 6 kişi sahada pozisyon alır. Smaçör atak yapar, blokçu (karşıda) topu geri yansıtır. Diğer 5 oyuncu coverage pozisyonunda alçalarak dönen topu kurtarır. 10 rally × 3 set.\n\nÖnemli Noktalar: Atakçı vurunca diğer herkes alçalsın. Üçgen pozisyon alın (atakçının arkasında ve yanlarında). Bloktan dönen top için her zaman hazır olun.", tags: ["oyun", "kaveraj", "takım"] },
  { id: 60, name: "Serve Receive + Atak", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6+", duration: "15 dk", desc: "Drilin Amacı: Servis karşılama formasyonundan organize atak tamamlama becerisini geliştirmek.\n\nUygulama: Servis atılır → karşılama formasyonundaki oyuncular manşetle karşılar → pasör set yapar → smaçör atak yapar. Her rotasyonda 5 rally, toplam 6 rotasyon.\n\nÖnemli Noktalar: Her rotasyonda karşılama sorumluluk alanları net olmalı. Pasör penetrasyonu hızlı olmalı. İlk pas kalitesi atağın kalitesini belirler.", tags: ["oyun", "serve receive", "atak"] },
  { id: 61, name: "Skor Baskısı Oyunu", phase: "Oyun", skill: "Taktik", level: "İleri", players: "12", duration: "15 dk", desc: "Drilin Amacı: Set sonu baskısını simüle ederek kritik anlarda karar verme ve mental dayanıklılık geliştirmek.\n\nUygulama: Set 20-20 skordan başlar. Normal kurallarla oynanır. 25 sayıya (veya 2 fark) kadar devam eder. Her set sonrasında takımlar yeniden düzenlenir.\n\nÖnemli Noktalar: Baskı altında basit oynayın, riskli ataklar yapmayın. Nefes kontrolü uygulayın. Her sayı arasında kısa bir reset yapın (derin nefes). Takım enerjisini yüksek tutun.", tags: ["oyun", "mental", "baskı"] },
  { id: 62, name: "Rotasyon Geçiş Drili", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6+", duration: "15 dk", desc: "Drilin Amacı: Her 6 rotasyonda pozisyon ve görev değişimlerini pekiştirmek, rotasyon geçişlerinde hata yapmamayı öğrenmek.\n\nUygulama: 6 oyuncu sahada pozisyon alır. Koç rotasyon çağırır, oyuncular pozisyon değiştirir. Her rotasyonda servis → karşılama → atak rally'si oynanır. 6 rotasyon = 1 tur, toplam 3 tur.\n\nÖnemli Noktalar: Her rotasyonda kimin nerede olduğunu ezberleyin. Geçiş anlarında hızlı hareket edin. Pasör penetrasyonu her rotasyonda farklı noktadan olabilir.", tags: ["oyun", "rotasyon"] },
  { id: 63, name: "3 Kişi Karşılama Formasyonu", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6", duration: "12 dk", desc: "Drilin Amacı: W-formasyonunda 3 kişilik servis karşılama dizilişini ve sorumluluk alanlarını pekiştirmek.\n\nUygulama: 3 karşılayıcı sahada W-formasyonunda (sol ön, orta arka, sağ ön) pozisyon alır. Servis atılır, en yakın oyuncu karşılar. 15 servis × 3 set. Her sette sorumluluk alanları değiştirilir.\n\nÖnemli Noktalar: Sorumluluk alanlarını belirleyin ve iletişim kurun. Araya düşen toplarda 'bende!' diye çağırın. Libero genellikle merkeze yakın olmalıdır.", tags: ["oyun", "karşılama", "formasyon"] },
  { id: 64, name: "Blok + Savunma Şeması", phase: "Oyun", skill: "Taktik", level: "İleri", players: "6", duration: "15 dk", desc: "Drilin Amacı: Blok pozisyonuna göre arkadaki savunmanın nasıl şekilleneceğini öğretmek, takım savunma şemasını pekiştirmek.\n\nUygulama: Koç karşı taraftan farklı pozisyonlardan atak simülasyonu yapar. Blokçular blok pozisyonu alır, savunmacılar bloğun kapattığı alana göre pozisyonlanır. 10 rally × 3 set.\n\nÖnemli Noktalar: Blokçunun arkasında durmayın, açık alanları kapatın. Savunma pozisyonu bloğun kapattığı açıya bağımlıdır. İletişim: Blokçu 'çizgi!' veya 'çapraz!' diye çağırmalı.", tags: ["oyun", "blok", "savunma", "şema"] },
  { id: 65, name: "Quick Attack Oyunu", phase: "Oyun", skill: "Taktik", level: "İleri", players: "6+", duration: "15 dk", desc: "Drilin Amacı: 1. tempo (quick) ağırlıklı hızlı atak sistemiyle oynama becerisini geliştirmek.\n\nUygulama: Normal oyun kurallarıyla oynanır ancak özel kural: Orta oyuncunun quick atağı 2 puan değerindedir. Bu, pasörü quick set yapmaya ve orta oyuncuyu aktif olmaya teşvik eder. 25 sayılık set.\n\nÖnemli Noktalar: Pasör-orta iletişimi kritik. Orta oyuncu her rallyde koşmaya hazır olmalı. Karşı taraf quick'e adaptasyon yapmalı.", tags: ["oyun", "quick", "hız"] },
  { id: 66, name: "Baskı Servisi Oyunu", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6+", duration: "12 dk", desc: "Drilin Amacı: Her serviste farklı hedef bölge belirlenerek agresif ve taktik servis atma becerisini geliştirmek.\n\nUygulama: Koç her servis öncesi hedef bölge (1-6) çağırır. Servis atan oyuncu o bölgeye isabet ettirmeye çalışır. İsabet: 2 puan, ace: 3 puan, hata: -1 puan. 10 servis × her oyuncu.\n\nÖnemli Noktalar: Zayıf karşılayıcıyı hedefleyin. Seam bölgesine (iki oyuncu arasına) servis atın. Risk/ödül dengesini koruyun.", tags: ["oyun", "servis", "baskı"] },
  { id: 67, name: "İletişim Drili", phase: "Oyun", skill: "Taktik", level: "Başlangıç", players: "6", duration: "10 dk", desc: "Drilin Amacı: Her dokunuşta sesli iletişim kurma alışkanlığı kazandırmak, takım koordinasyonunu artırmak.\n\nUygulama: Normal oyun kurallarıyla oynanır ancak özel kural: Her dokunuşte oyuncu sesli çağırmalıdır ('bende!', 'dış!', 'kısa!'). Çağrı yapılmadan dokunuş olursa karşı takıma puan verilir.\n\nÖnemli Noktalar: İletişim her zaman ses tonuyla yapılmalı (fısıltı yetmez). Servis gelirken karşılayacak kişi 'bende!' demeli. Savunmada pozisyon çağrısı yapılmalı.", tags: ["oyun", "iletişim", "temel"] },
  { id: 68, name: "Tempo Değişimi Oyunu", phase: "Oyun", skill: "Taktik", level: "İleri", players: "6+", duration: "15 dk", desc: "Drilin Amacı: Set tempolarını sürekli değiştirerek rakip blokçuyu şaşırtma taktiklerini geliştirmek.\n\nUygulama: Pasör her sette farklı tempo kullanır: 1. tempo (quick), 2. tempo (orta hız), 3. tempo (yüksek set). Aynı rally içinde tempoları değiştirir. Normal oyun kuralları. 25 sayılık set.\n\nÖnemli Noktalar: Tempo değişimi rakibi şaşırtır. Pasör-atakçı iletişimi şart. Atakçılar farklı tempolara adapte olabilmeli.", tags: ["oyun", "tempo", "taktik"] },
  { id: 69, name: "Cross-court vs Line Oyunu", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6+", duration: "12 dk", desc: "Drilin Amacı: Atakçıların çapraz ve çizgi atak arasında doğru karar verme becerisini geliştirmek.\n\nUygulama: Normal oyun kurallarıyla oynanır. Koç her atak öncesi 'çapraz!' veya 'çizgi!' çağırır, smaçör çağrılan yöne vurmak zorundadır. İleri seviyede: smaçör bloğu okuyarak kendi kararını verir.\n\nÖnemli Noktalar: Bloğun kapattığı yöne vurmayın. Bilek açısıyla yön değiştirebilmelisiniz. Karar verme hızı kritik.", tags: ["oyun", "atak", "karar"] },
  { id: 70, name: "Coverage Rallisi", phase: "Oyun", skill: "Taktik", level: "Orta", players: "6", duration: "15 dk", desc: "Drilin Amacı: Sürekli atak coverage (kaveraj) pozisyonu alarak bloktan dönen topları kurtarma alışkanlığı kazandırmak.\n\nUygulama: Her atakta diğer 5 oyuncu coverage pozisyonunda alçalır. Blokçu (karşıda) topu geri yansıtır. Coverage yapan oyuncular topu kurtarır ve yeni atak düzenlenir. Rally durana kadar sürer. 10 rally × 3 set.\n\nÖnemli Noktalar: Atakçı vurunca herkes alçalsın. Üçgen pozisyon alın. Coverage sonrası hemen tekrar atak organize edin.", tags: ["oyun", "coverage"] },
];

// ===== SOĞUMA DRİLLERİ (15) =====
export const cooldownDrills: Drill[] = [
  { id: 71, name: "Omuz Germe ve Mobilite", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "5 dk", desc: "Drilin Amacı: Antrenman sonrası smaç ve servis ile yüklenen omuz kaslarını germek, esnekliği korumak ve yaralanma riskini azaltmak.\n\nUygulama: (1) Kolu göğsün önünden karşı tarafa çekin, 20 sn tutun. (2) Kolu başınızın arkasına atıp dirseği diğer elle çekin, 20 sn. (3) Bant ile omuz distalasyonu, 20 sn her yön. Her germe 2 tekrar.\n\nÖnemli Noktalar: Yavaş ve kontrollü gerin, sert çekmeyin. Ağrı hissederseniz açıyı azaltın. Nefes almaya devam edin.", tags: ["soğuma", "omuz", "germe"] },
  { id: 72, name: "Hamstring Germe", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Arka bacak (hamstring) kaslarını statik germek, esnekliği artırmak ve kas ağrısını azaltmak.\n\nUygulama: (1) Oturarak: Bacakları öne uzatın, parmak uçlarına uzanın, 30 sn tutun. (2) Ayakta: Bir ayağı öne uzatın, kalçadan öne eğilin, 30 sn tutun. Her iki bacak ayrı ayrı. 2 tekrar.\n\nÖnemli Noktalar: Dizleri bükmeyin (olabildiğince düz tutun). Sırtınızı düz tutun, belden eğilmeyin. Ağrı değil gerginlik hissetmelisiniz.", tags: ["soğuma", "bacak", "germe"] },
  { id: 73, name: "Quadriceps Germe", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Ön bacak (quadriceps) kaslarını germek, diz sağlığını korumak ve sıçrama sonrası kas kısalmasını önlemek.\n\nUygulama: Ayakta durun, bir ayağınızı arkadan kalçanıza çekin, aynı taraf elle tutun. Dizler birbirine paralel olmalı. 30 sn tutun, taraf değiştirin. 2 tekrar.\n\nÖnemli Noktalar: Denge için duvara veya partnere tutunabilirsiniz. Diz öne çıkmamalı, aşağı bakmalı. Beli zorlamayın, gövde dik olmalı.", tags: ["soğuma", "bacak", "germe"] },
  { id: 74, name: "Kalça Açıcı (Hip Opener)", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Kalça esnekliğini artırmak, voleybolda sıçrama ve savunma pozisyonları için kalça mobilitesini geliştirmek.\n\nUygulama: (1) Kelebek germe: Oturarak ayak tabanlarını birleştirin, dizleri yanlara açın, 30 sn. (2) Güvercin pozu: Bir bacağı önde 90° bükün, diğerini geriye uzatın, 30 sn her taraf.\n\nÖnemli Noktalar: Zorlamayın, doğal açıklığınızı kullanın. Nefes almaya devam edin. Düzenli yaparak esnekliğiniz artacaktır.", tags: ["soğuma", "kalça", "esneklik"] },
  { id: 75, name: "Sırt Germe (Cat-Cow)", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Omurga mobilitesini artırmak, antrenman sonrası sırt kaslarını rahatlatmak.\n\nUygulama: Dört ayak pozisyonunda (eller omuz altında, dizler kalça altında): (1) Cat: Nefes verin, sırtı tavana doğru yuvarlayın, çeneyi göğse yapıştırın. (2) Cow: Nefes alın, karnı yere doğru indirin, başı yukarı kaldırın. 10 tekrar, yavaş tempo.\n\nÖnemli Noktalar: Hareketi nefesle senkronize edin. Yavaş ve kontrollü yapın. Bel bölgesinde ağrı varsa hareket genliğini azaltın.", tags: ["soğuma", "sırt"] },
  { id: 76, name: "Triceps ve Göğüs Germe", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "2 dk", desc: "Drilin Amacı: Smaç ve servis hareketi sonrası kol arkası (triceps) ve göğüs kaslarını germek.\n\nUygulama: (1) Triceps: Kolu başınızın arkasına atın, diğer elle dirseği çekin, 20 sn her kol. (2) Göğüs: Kapı kenarı veya duvar köşesinde kolu 90° açarak göğsü açın, 20 sn her taraf.\n\nÖnemli Noktalar: Gerginlik hissedecek kadar gerin, ağrı olmamalı. Nefes almaya devam edin. Her iki tarafı eşit süre gerin.", tags: ["soğuma", "kol", "germe"] },
  { id: 77, name: "Baldır Germe", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "2 dk", desc: "Drilin Amacı: Sıçrama sonrası baldır kaslarını (gastrocnemius ve soleus) germek, ayak bileği sağlığını korumak.\n\nUygulama: Duvara yaslanarak: (1) Gastrocnemius: Arka bacak düz, topuğu yere basarak öne eğilin, 30 sn. (2) Soleus: Arka bacak hafif bükülü, topuğu yere basarak öne eğilin, 30 sn. Her bacak 2 tekrar.\n\nÖnemli Noktalar: Topuğu yerden kaldırmayın. Her iki kasın ayrı ayrı gerildiğinden emin olun. Yavaş ve kontrollü gerin.", tags: ["soğuma", "baldır"] },
  { id: 78, name: "Hafif Koşu ile Soğuma", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Kalp atış hızını kademeli olarak düşürmek, laktik asit birikimini azaltmak ve toparlanmayı hızlandırmak.\n\nUygulama: Çok düşük tempoda salon çevresinde koşu. Tempolu bir yürüyüşten biraz hızlı olmalı. Son 1 dakikada yürüyüşe geçin.\n\nÖnemli Noktalar: Konuşabilecek tempoda koşun. Ani durma yapmayın, tempoyu kademeli düşürün. Derin nefes alın.", tags: ["soğuma", "kardio"] },
  { id: 79, name: "Derin Nefes Egzersizi", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Parasempatik sinir sistemini aktive ederek vücudu dinlenme moduna geçirmek, stresi azaltmak ve toparlanmayı hızlandırmak.\n\nUygulama: Oturarak veya sırt üstü yatarak: (1) 4 saniye burundan nefes alın. (2) 7 saniye nefes tutun. (3) 8 saniye ağızdan yavaşça verin. Bu döngüyü 5-6 kez tekrarlayın.\n\nÖnemli Noktalar: Gözlerinizi kapatın. Düşüncelerinizi sadece nefese yönlendirin. Karın bölgenizi nefesle şişirin (diyafram nefesi).", tags: ["soğuma", "nefes", "dinlenme"] },
  { id: 80, name: "Foam Roller Sırt", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Üst sırt kaslarındaki gerginliği azaltmak, miyofasiyal gevşeme sağlamak ve omurga mobilitesini artırmak.\n\nUygulama: Foam roller'ı üst sırtın altına yerleştirin. Dizleri bükük, ayaklar yerde. Yavaşça ileri geri yuvarlayın. Gergin noktalarda 15-20 sn durun.\n\nÖnemli Noktalar: Bel bölgesinde foam roller kullanmayın. Çok güçlü basınç uygulamayın. Nefes almaya devam edin.", tags: ["soğuma", "foam roller", "masaj"] },
  { id: 81, name: "Foam Roller IT Band", phase: "Soğuma", skill: "Genel", level: "Orta", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Dış bacak (IT band) gerginliğini azaltmak, diz sağlığını korumak ve lateral hareket sonrası kasları rahatlatmak.\n\nUygulama: Yan pozisyonda foam roller'ı dış bacağın altına yerleştirin. Kalçadan dize kadar yavaşça yuvarlayın. Gergin noktalarda 15-20 sn durun. Her bacak 2 dakika.\n\nÖnemli Noktalar: Başlangıçta çok ağrılı olabilir, yavaş başlayın. Diz kapağının üzerinden geçmeyin. Diğer bacağınızla destek alarak basıncı ayarlayın.", tags: ["soğuma", "foam roller"] },
  { id: 82, name: "Bel ve Core Germe", phase: "Soğuma", skill: "Core", level: "Başlangıç", players: "1+", duration: "3 dk", desc: "Drilin Amacı: Core ve bel kaslarını germek, omurga sağlığını korumak ve antrenman sonrası kas gerginliğini azaltmak.\n\nUygulama: (1) Çocuk pozu: Dizler üzerinde kalçayı topuklara oturtun, kolları öne uzatın, 30 sn. (2) Bel rotasyonu: Sırt üstü yatın, dizleri bir tarafa düşürün, omuzlar yerde kalmalı, 20 sn her taraf.\n\nÖnemli Noktalar: Hareketleri yavaş ve kontrollü yapın. Bel ağrısı varsa hareket genliğini azaltın. Nefes almaya devam edin.", tags: ["soğuma", "bel", "core"] },
  { id: 83, name: "Boyun Germe", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "1+", duration: "2 dk", desc: "Drilin Amacı: Antrenman sırasında sürekli yukarı bakma (blok, smaç izleme) sonrası boyun kaslarını rahatlatmak.\n\nUygulama: (1) Lateral: Başı yana eğin, üstteki elle hafifçe çekin, 20 sn her taraf. (2) Anterior: Çeneyi göğse doğru indirin, elleri başın arkasına koyun, hafifçe çekin, 20 sn. (3) Rotasyon: Başı yavaşça sağa ve sola çevirin, 10 tekrar.\n\nÖnemli Noktalar: Çok sert çekmeyin, hafif gerginlik yeterli. Ani hareketler yapmayın. Baş dönmesi olursa durun.", tags: ["soğuma", "boyun"] },
  { id: 84, name: "Partner Germe", phase: "Soğuma", skill: "Genel", level: "Başlangıç", players: "2", duration: "5 dk", desc: "Drilin Amacı: Partner yardımıyla daha derin ve etkili germe yapmak, takım bağını güçlendirmek.\n\nUygulama: (1) Hamstring: Sırt üstü yatan partner bacağını yukarı kaldırır, diğeri hafifçe iterek daha derin germe sağlar, 30 sn. (2) Omuz: Partner arkadan kolları kavrar ve hafifçe geriye çeker, 20 sn. (3) Sırt: Sırt sırta oturarak bir partner öne eğilir, diğerini sırtında gerer, 20 sn.\n\nÖnemli Noktalar: Partner iletişim kursun: 'Yeterli mi?', 'Daha fazla olabilir mi?'. Asla ağrı noktasına kadar itmeyin. Yavaş ve kontrollü.", tags: ["soğuma", "partner"] },
  { id: 85, name: "Yoga Akışı (5 dk)", phase: "Soğuma", skill: "Genel", level: "Orta", players: "1+", duration: "5 dk", desc: "Drilin Amacı: Tüm vücudu kapsayan yoga akışıyla derinlemesine germe, nefes kontrolü ve zihinsel dinlenme sağlamak.\n\nUygulama: Akış sırası: (1) Aşağı bakan köpek (30 sn) → (2) Plank (15 sn) → (3) Cobra (20 sn) → (4) Çocuk pozu (30 sn) → (5) Oturarak öne eğilme (30 sn) → (6) Savasana (1 dk, sırt üstü dinlenme).\n\nÖnemli Noktalar: Her pozisyonda nefese odaklanın. Geçişler yavaş ve akıcı olmalı. Zorlanıyorsanız pozisyonu kolaylaştırın.", tags: ["soğuma", "yoga", "esneklik"] },
];

// ===== EK ANA ANTRENMAN DRİLLERİ (20) =====
export const additionalDrills: Drill[] = [
  { id: 86, name: "Pasör Penetrasyon Drili", phase: "Ana Antrenman", skill: "Pasörlük", level: "Orta", players: "3+", duration: "12 dk", desc: "Drilin Amacı: Pasörün arka sıradan file kenarına hızlı ve doğru şekilde koşarak set pozisyonu alma becerisini geliştirmek.\n\nUygulama: Pasör 1, 6 veya 5 numaradan başlar (arka sıra). Top oyuna girdiğinde hızla file kenarındaki set pozisyonuna (2-3 arası) koşar ve gelen topu set yapar. Her pozisyondan 10 tekrar × 2 set.\n\nÖnemli Noktalar: Koşu yolu diğer oyuncularla çakışmamalı. Set pozisyonuna ulaşmadan topu karşılamayın. Penetrasyon hızı her zaman yüksek tutulmalı.", tags: ["pasör", "penetrasyon"] },
  { id: 87, name: "Hızlı Tempo Atak (Quick)", phase: "Ana Antrenman", skill: "Atak", level: "İleri", players: "3", duration: "15 dk", desc: "Drilin Amacı: 1. tempo (quick) orta atak zamanlama mükemmelliğini sağlamak, pasör-orta oyuncu senkronizasyonunu geliştirmek.\n\nUygulama: Pasör file kenarında, orta oyuncu 2 metre geride hazırlanır. Koç topu pasöre gönderir, orta oyuncu koşmaya başlar. Pasör topu tam doğru yükseklik ve zamanda bırakır, orta oyuncu havada karşılar ve atak yapar. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Orta oyuncu, pasörden önce koşmaya başlamalı (erken kalkış). Göz teması kritik. Set çok yüksek olmamalı, orta oyuncunun el hizasında olmalı.", tags: ["atak", "quick", "tempo"] },
  { id: 88, name: "Slide Atak", phase: "Ana Antrenman", skill: "Atak", level: "İleri", players: "3", duration: "12 dk", desc: "Drilin Amacı: Tek ayak zıplama ile kayarak atak yapma tekniğini (slide) öğretmek, orta oyuncunun ofansif çeşitliliğini artırmak.\n\nUygulama: Orta oyuncu pasörün yanından başlar ve anten yönüne doğru koşarak kayar. Pasör orta oyuncunun koşu ritmine göre set verir. Orta oyuncu tek ayakla (sol ayak) zıplar ve atak yapar. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Son adım sol ayakla olmalı (tek ayak sıçrama). Koşu ritmi ve set zamanlaması eş zamanlı olmalı. Kol mekaniği normal smaçtan farklı, daha açık açıyla vurulur.", tags: ["atak", "slide", "orta"] },
  { id: 89, name: "Piston Blok Drili", phase: "Ana Antrenman", skill: "Blok", level: "İleri", players: "3+", duration: "12 dk", desc: "Drilin Amacı: Ardışık blok yapma dayanıklılığını artırmak, blok sonrası hızlı toparlanma ve tekrar blok pozisyonu alma becerisini geliştirmek.\n\nUygulama: Blokçu filede sürekli blok → iniş → kayma → blok yapar. Koç sağdan ve soldan atak simülasyonu yapar. Blokçu 30 saniye aralıksız blok yapar, 30 saniye dinlenir. 5 set.\n\nÖnemli Noktalar: İniş sonrası hemen dizleri bükün ve hazır olun. Lateral kayma hızını artırın. Kondisyon gerektiren bir dril, tempo önemli.", tags: ["blok", "dayanıklılık"] },
  { id: 90, name: "Overhand Dig", phase: "Ana Antrenman", skill: "Savunma", level: "Orta", players: "2", duration: "8 dk", desc: "Drilin Amacı: Yüksek gelen topspin topları üstten (overhead) savunma tekniğini öğretmek.\n\nUygulama: Partner yüksek ve hızlı top atar (topspin simülasyonu). Oyuncu üstten (set pozisyonunda) savunma yapar, topu kontrol ederek yukarı kaldırır. 15 tekrar × 3 set.\n\nÖnemli Noktalar: Ellerinizi sert tutun, parmakları açık. Topspin toplar sert gelir, bileklerinizi hazır tutun. Bu teknik sadece yüksek gelen toplar için kullanılır.", tags: ["savunma", "üstten"] },
  { id: 91, name: "Servis Karşılama + Quick", phase: "Ana Antrenman", skill: "Taktik", level: "İleri", players: "6+", duration: "15 dk", desc: "Drilin Amacı: Servis karşılama sonrası hızlı atak (quick) organizasyonunu geliştirmek, tüm sürecin akıcı olmasını sağlamak.\n\nUygulama: Servis atılır → karşılama yapılır → pasör hızla pozisyona koşar → orta oyuncu quick koşusuna başlar → pasör quick set yapar → orta oyuncu atak yapar. 10 rally × 3 set.\n\nÖnemli Noktalar: İlk pas kalitesi quick atağı mümkün kılar. Kötü pas gelirse pasör güvenli dış set yapmalı. Orta oyuncu her rally'de koşmaya hazır olmalı.", tags: ["taktik", "quick", "karşılama"] },
  { id: 92, name: "Cross Step Blok", phase: "Ana Antrenman", skill: "Blok", level: "Orta", players: "2+", duration: "10 dk", desc: "Drilin Amacı: Çapraz adım (cross-step) tekniğiyle file boyunca uzun mesafe hareket ederek blok pozisyonu alma becerisini geliştirmek.\n\nUygulama: Blokçu file ortasında başlar. Koçun işaretiyle sağa veya sola çapraz adımla koşar ve köşede blok zıplaması yapar. İç ayak önce çapraz adım atar, sonra dış ayak kapanır ve çift ayakla zıplanır. Her yön 10 tekrar × 2 set.\n\nÖnemli Noktalar: İlk adım çapraz, ikinci adım kapanma. Son adımda ayakları paralele getirin. Elleri zıplama sırasında yukarı tutun.", tags: ["blok", "çapraz adım"] },
  { id: 93, name: "Savunma Okuma Drili", phase: "Ana Antrenman", skill: "Savunma", level: "Orta", players: "4+", duration: "12 dk", desc: "Drilin Amacı: Atakçının vücut dilini (omuz açısı, kol hareketi, bakış yönü) okuyarak savunma pozisyonunu önceden ayarlama becerisini geliştirmek.\n\nUygulama: Smaçör farklı yönlere atak yapar (çapraz, çizgi, tip). Savunmacı smaçörün omuz ve kol hareketini izleyerek pozisyon alır. 15 atak × 3 set.\n\nÖnemli Noktalar: Gözleriniz atakçının omzunda olsun. Kol açısı atak yönünü ele verir. Erken hareket edin ama taahhüt etmeden önce emin olun.", tags: ["savunma", "okuma"] },
  { id: 94, name: "Set Location Drili", phase: "Ana Antrenman", skill: "Pasörlük", level: "Orta", players: "3", duration: "12 dk", desc: "Drilin Amacı: Farklı set lokasyonlarına (4 numara, 2 numara, arka sıra, quick) hassas ve tutarlı set gönderme becerisini geliştirmek.\n\nUygulama: Koç topu pasöre farklı noktalardan gönderir. Pasör çağrılan lokasyona (dış, sırt, pipe, quick) set yapar. Hedef bölgeler cone ile işaretlenir. 15 set × 3 set.\n\nÖnemli Noktalar: Set yüksekliği ve hızı lokasyona göre değişmeli. Dış set: yüksek ve anten hizasına. Quick: düşük ve hızlı. Sırt set: gözüyle aldatma yapabilmeli.", tags: ["pasör", "doğruluk"] },
  { id: 95, name: "Continuous Rally Drili", phase: "Ana Antrenman", skill: "Taktik", level: "Orta", players: "12", duration: "15 dk", desc: "Drilin Amacı: Durmaksızın rally sürdürerek takım organizasyonu, geçiş hızı ve dayanıklılık geliştirmek.\n\nUygulama: İki takım 6'şar kişi ile oynar. Özel kural: Her rally en az 6 dokunuş sürmeli (3 her taraf). 6 dokunuştan önce biten rally sayılmaz. 15 dakika sürekli oyun.\n\nÖnemli Noktalar: Kontrollü oynayın, topu oyunda tutmaya çalışın. Geçiş hızına dikkat edin. Yorulunca formu bozmayın.", tags: ["taktik", "rally", "sürekli"] },
  { id: 96, name: "Dengesiz Top Drili", phase: "Ana Antrenman", skill: "Savunma", level: "İleri", players: "2", duration: "8 dk", desc: "Drilin Amacı: Beklenmedik yönlerden ve açılardan gelen toplara tepki vererek refleks ve adaptasyon becerisi geliştirmek.\n\nUygulama: Koç oyuncunun arkasından, yanından veya beklenmedik açılardan top atar. Oyuncu duyduğu veya gördüğü anda tepki vererek topu kurtarır. 20 top × 3 set.\n\nÖnemli Noktalar: Sürekli hazır pozisyonda kalın. Duyduğunuz sese veya gördüğünüz harekete anında tepki verin. Bu dril maç içi sürpriz topları simüle eder.", tags: ["savunma", "refleks"] },
  { id: 97, name: "İki Top Drili", phase: "Ana Antrenman", skill: "Genel", level: "Orta", players: "4", duration: "10 dk", desc: "Drilin Amacı: İki topla eş zamanlı oynayarak konsantrasyon, çevresel farkındalık ve koordinasyon geliştirmek.\n\nUygulama: 4 oyuncu kare şeklinde durur. İki top aynı anda oyuna girer. Her oyuncu bir topu alıp diğer yöne gönderir. Toplar çakışmamalı ve yere düşmemeli. 3 dakika aralıksız.\n\nÖnemli Noktalar: İki topu da takip etmeye çalışın. İletişim kritik: 'sende!', 'bende!'. Başlangıçta yavaş başlayın, tempo kademeli artırılır.", tags: ["eğlence", "konsantrasyon"] },
  { id: 98, name: "Joker Oyuncu Drili", phase: "Ana Antrenman", skill: "Taktik", level: "Orta", players: "7+", duration: "15 dk", desc: "Drilin Amacı: Sürekli değişen takım yapısına adaptasyon becerisi geliştirmek, hem atak hem savunma yapabilme esnekliği kazandırmak.\n\nUygulama: 3'e 3 oynanır, bir 'joker' oyuncu her zaman topu alan tarafa katılır (4'e 3 avantaj). Sayı alan taraf servis atar. Joker her rally'de taraf değiştirir. 15 sayılık set.\n\nÖnemli Noktalar: Joker hızla taraf değiştirmeli. Avantajlı taraf bunu kullanmayı bilmeli. Adaptasyon hızı çok önemli.", tags: ["taktik", "adaptasyon"] },
  { id: 99, name: "Kondisyon Shuttle", phase: "Ana Antrenman", skill: "Kondisyon", level: "Orta", players: "1+", duration: "8 dk", desc: "Drilin Amacı: Saha çizgileri arasında mekik koşusu yaparak hız, çeviklik ve anaerobik dayanıklılık geliştirmek.\n\nUygulama: Temel çizgiden başlayın. (1) 3 metre çizgisine koşup dönün. (2) 6 metre çizgisine koşup dönün. (3) 9 metre çizgisine koşup dönün. 1 tur = 36 metre. 30 saniye dinlenme ile 5 tur.\n\nÖnemli Noktalar: Her dönüşte çizgiye dokunun. Dönüşlerde dizleri bükün, sert fren yapmayın. Zamanınızı ölçerek gelişiminizi takip edin.", tags: ["kondisyon", "koşu"] },
  { id: 100, name: "Reaksiyon Topları", phase: "Ana Antrenman", skill: "Savunma", level: "Orta", players: "2", duration: "8 dk", desc: "Drilin Amacı: Düzensiz zıplayan reaksiyon topuyla refleks, el-göz koordinasyonu ve tepki hızını geliştirmek.\n\nUygulama: Reaksiyon topu (altıgen veya düzensiz şekilli) 2-3 metre mesafeden yere atılır. Topu yakalamaya çalışın. Her turda 20 atış × 3 set.\n\nÖnemli Noktalar: Düşük pozisyonda hazır olun. Topun zıplama yönünü tahmin etmeye çalışmayın, tepki verin. Reaksiyon topu yoksa normal topu duvardan sektirerek kullanabilirsiniz.", tags: ["savunma", "refleks", "reaksiyon"] },
  { id: 101, name: "Servis + Chase Drili", phase: "Ana Antrenman", skill: "Servis", level: "Orta", players: "2+", duration: "10 dk", desc: "Drilin Amacı: Servis attıktan sonra hızla savunma pozisyonuna geçiş yapabilmeyi geliştirmek, maç içi geçiş hızını artırmak.\n\nUygulama: Oyuncu servis atar → hemen sahaya koşar → base pozisyonunu alır → koç top atar → oyuncu savunma yapar. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Servis sonrası beklemeyin, hemen koşmaya başlayın. Base pozisyonuna ulaşmadan top gelebilir, hazır olun. Kondisyon gerektiren bir dril.", tags: ["servis", "geçiş", "kondisyon"] },
  { id: 102, name: "Setter Dump", phase: "Ana Antrenman", skill: "Pasörlük", level: "İleri", players: "3+", duration: "10 dk", desc: "Drilin Amacı: Pasörün 2. dokunuşta direkt atak yapma (dump) tekniğini öğrenmek, sürpriz skor fırsatları yaratmak.\n\nUygulama: Pasör normal set pozisyonunda topu karşılar. Son anda set yerine topu parmak uçlarıyla karşı sahaya (bloğun arkasına) düşürür. Dump'ı normal set ile karıştırarak çalışılır: 5 set + 5 dump, rastgele sırada. 3 set.\n\nÖnemli Noktalar: Dump öncesi set yapacakmış gibi görünün. Blokçunun pozisyonunu izleyin, boş bölgeye düşürün. Aşırı kullanmayın, sürpriz etkisi kaybolur.", tags: ["pasör", "dump", "sürpriz"] },
  { id: 103, name: "3 Kişi Sürekli Savunma", phase: "Ana Antrenman", skill: "Savunma", level: "İleri", players: "3+", duration: "10 dk", desc: "Drilin Amacı: 3 oyuncu arasında sürekli top dolaşımıyla savunma dayanıklılığı, toparlanma hızı ve takım savunma koordinasyonu geliştirmek.\n\nUygulama: 3 savunmacı sahada üçgen pozisyonda durur. Koç sürekli top atar (farklı yön ve şiddetlerde). Her kurtarıştan sonra top koça geri gider ve hemen yeni top gelir. 2 dakika aralıksız × 3 set.\n\nÖnemli Noktalar: Her kurtarış sonrası hemen hazır pozisyona dönün. Sorumluluk alanlarınızı bilin. İletişim sürekli olmalı.", tags: ["savunma", "dayanıklılık"] },
  { id: 104, name: "Parmak Ucu Kontrol", phase: "Ana Antrenman", skill: "Pas", level: "Başlangıç", players: "1", duration: "8 dk", desc: "Drilin Amacı: Parmak uçlarıyla top kontrol becerisini geliştirmek, set tekniğinin temelini oluşturmak.\n\nUygulama: Kendi kendinize topu yukarı set yapın ve tekrar karşılayın. (1) Yerinde: 30 ardışık set. (2) Yürüyerek: 20 set. (3) Oturarak: 20 set. Her aşama 3 set.\n\nÖnemli Noktalar: Parmak uçlarıyla temasa geçin, avuç içi değmesin. Üçgen el şeklini koruyun. Top alın hizasında karşılanmalı. Bilek ve parmak gücüyle itin.", tags: ["pas", "temel", "kontrol"] },
  { id: 105, name: "Cone Atak Drili", phase: "Ana Antrenman", skill: "Atak", level: "Orta", players: "3+", duration: "12 dk", desc: "Drilin Amacı: Koniler arasından yaklaşma ve hedef odaklı atak yapma becerisini geliştirmek, yön değişimi ve çeviklik kazandırmak.\n\nUygulama: 3-4 koni zigzag şeklinde yerleştirilir. Smaçör konilerin arasından slalom yaparak koşar, file kenarına ulaşır ve pasörden gelen seti vurur. Hedef: sahada işaretlenmiş bölgelere atak. 10 tekrar × 3 set.\n\nÖnemli Noktalar: Konilerin arasında hız kaybetmeyin. Son adımlarda smaç yaklaşmasına geçin. Hedef doğruluğu güçten daha önemli.", tags: ["atak", "hedef", "çeviklik"] },
];


